import { eq } from "drizzle-orm";
import { getDb } from "@/server/db";
import { issues } from "@/server/db/schema/issues";
import { notifications } from "@/server/db/schema/notifications";
import { activityEvents } from "@/server/db/schema/activity";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import {
  createTenant,
  issueInput,
  useTemporaryDatabase,
} from "@/tests/server/_support/fixtures";
import type { IsoTimestamp } from "@/types/common";

const STAMP = "2026-03-01T09:00:00.000Z" as IsoTimestamp;
const OLDER = "2026-03-01T08:00:00.000Z" as IsoTimestamp;

async function walk<T extends { id: string }>(
  label: string,
  limit: number,
  full: readonly T[],
  pageOf: (cursor: string | null) => Promise<{ items: readonly T[]; nextCursor: string | null; total: number }>,
): Promise<void> {
  const seen: string[] = [];
  let cursor: string | null = null;
  const cursors = new Set<string>();
  for (let i = 0; i < 20; i += 1) {
    const page = await pageOf(cursor);
    if (page.total !== full.length) {
      throw new Error(`${label} total ${page.total} != ${full.length}`);
    }
    seen.push(...page.items.map((row) => row.id));
    if (!page.nextCursor) break;
    if (cursors.has(page.nextCursor)) throw new Error(`${label} cursor loop`);
    cursors.add(page.nextCursor);
    cursor = page.nextCursor;
  }
  const fullIds = full.map((row) => row.id);
  if (seen.join(",") !== fullIds.join(",")) {
    throw new Error(
      `${label} limit ${limit}\n paged ${seen.join(",")}\n full  ${fullIds.join(",")}`,
    );
  }
  console.log(`ok ${label} limit=${limit} n=${seen.length}`);
}

async function main(): Promise<void> {
  const cleanup = await useTemporaryDatabase();
  try {
    const north = await createTenant("north");
    const other = await createTenant("other");

    const inserted = [];
    for (let i = 0; i < 4; i += 1) {
      const number = await issueRepo.nextIssueNumber(north.org.id, north.project.id);
      inserted.push(
        await issueRepo.insertIssue(
          issueInput(north.org.id, north.project.id, { title: `Bulk ${i} title` }),
          north.userIds.owner,
          number,
        ),
      );
    }
    for (let i = 0; i < 3; i += 1) {
      const number = await issueRepo.nextIssueNumber(north.org.id, north.project.id);
      inserted.push(
        await issueRepo.insertIssue(
          issueInput(north.org.id, north.project.id, { title: `Older ${i} title` }),
          north.userIds.owner,
          number,
        ),
      );
    }
    for (let i = 0; i < 5; i += 1) {
      const number = await issueRepo.nextIssueNumber(other.org.id, other.project.id);
      await issueRepo.insertIssue(
        issueInput(other.org.id, other.project.id, { title: `Other ${i} title` }),
        other.userIds.owner,
        number,
      );
    }

    const db = getDb();
    const northIds = inserted.map((row) => row.id);
    db.update(issues)
      .set({ createdAt: STAMP })
      .where(eq(issues.orgId, north.org.id))
      .run();
    // Make the last three older so the tie is not the whole set.
    for (const id of northIds.slice(4)) {
      db.update(issues).set({ createdAt: OLDER }).where(eq(issues.id, id)).run();
    }
    db.update(issues)
      .set({ createdAt: STAMP })
      .where(eq(issues.orgId, other.org.id))
      .run();

    const full = await issueRepo.listIssues({
      orgId: north.org.id,
      projectId: north.project.id,
      limit: 100,
      cursor: null,
    });
    if (full.items.length !== 7) throw new Error(`full page ${full.items.length}`);
    if (full.items.some((row) => row.orgId !== north.org.id)) {
      throw new Error("full page leaked");
    }

    for (const limit of [1, 2, 3, 6, 7]) {
      await walk("issues", limit, full.items, (cursor) =>
        issueRepo.listIssues({
          orgId: north.org.id,
          projectId: north.project.id,
          limit,
          cursor,
        }),
      );
    }

    await notificationRepo.insertNotifications(
      north.org.id,
      Array.from({ length: 7 }, (_, i) => ({
        recipientId: north.userIds.owner,
        kind: "issue_assigned" as const,
        title: `Assigned ${i}`,
        body: "body",
        href: "/x",
        actorId: north.userIds.admin,
        channels: ["in_app" as const],
      })),
    );
    await notificationRepo.insertNotifications(
      other.org.id,
      Array.from({ length: 4 }, (_, i) => ({
        recipientId: other.userIds.owner,
        kind: "issue_assigned" as const,
        title: `Other ${i}`,
        body: "body",
        href: "/x",
        actorId: other.userIds.admin,
        channels: ["in_app" as const],
      })),
    );

    const notes = await notificationRepo.listNotifications({
      orgId: north.org.id,
      recipientId: north.userIds.owner,
      unreadOnly: false,
      limit: 100,
      cursor: null,
    });
    if (notes.total !== 7 || notes.items.length !== 7) {
      throw new Error(`notes ${notes.items.length}/${notes.total}`);
    }
    for (const limit of [1, 2, 3, 6]) {
      await walk("notes", limit, notes.items, (cursor) =>
        notificationRepo.listNotifications({
          orgId: north.org.id,
          recipientId: north.userIds.owner,
          unreadOnly: false,
          limit,
          cursor,
        }),
      );
    }

    for (let i = 0; i < 7; i += 1) {
      await activityRepo.insertActivity({
        orgId: north.org.id,
        action: "issue.updated",
        actorId: north.userIds.owner,
        subjectKind: "issue",
        subjectId: northIds[0]!,
        projectId: north.project.id,
        summary: `changed ${i}`,
        metadata: {},
        occurredAt: STAMP,
      });
    }
    for (let i = 0; i < 3; i += 1) {
      await activityRepo.insertActivity({
        orgId: other.org.id,
        action: "issue.updated",
        actorId: other.userIds.owner,
        subjectKind: "issue",
        subjectId: northIds[0]!,
        projectId: other.project.id,
        summary: `other ${i}`,
        metadata: {},
        occurredAt: STAMP,
      });
    }
    const audit = await activityRepo.listActivity({
      orgId: north.org.id,
      limit: 100,
      cursor: null,
    });
    if (audit.items.length !== 7) throw new Error(`audit ${audit.items.length}`);
    for (const limit of [1, 2, 4]) {
      await walk("audit", limit, audit.items, (cursor) =>
        activityRepo.listActivity({
          orgId: north.org.id,
          limit,
          cursor,
        }),
      );
    }

    console.log("all ok");
  } finally {
    cleanup();
  }
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

